using System.Globalization;namespace OdinVault.Manager.Wpf.Infrastructure;internal static class PersianDateFormatter{static readonly PersianCalendar Calendar=new();public static string Format(DateTime? value,bool time=true){if(value is null)return "—";var d=value.Value.Kind==DateTimeKind.Utc?value.Value.ToLocalTime():value.Value;var date=$"{Calendar.GetYear(d):0000}/{Calendar.GetMonth(d):00}/{Calendar.GetDayOfMonth(d):00}";return time?$"{date} {d:HH:mm}":date;}}